def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_me = me[-1]
    last_opp = opp[-1]
    opp_c = opp.count('C')
    opp_d = n - opp_c

    if n >= 10:
        rd = opp[-10:].count('D')
        if rd >= 8:
            return 'D'
        if rd == 0:
            if last_me == 'D':
                return 'C'
            if n >= 99:
                return 'D'
            if n % 9 == 5:
                return 'D'
            return 'C'
        if rd <= 2 and last_opp == 'C':
            if last_me == 'D':
                return 'C'
            return 'C'

    if last_opp == 'D':
        if last_me == 'D':
            run_d = 0
            for a in reversed(opp):
                if a == 'D':
                    run_d += 1
                else:
                    break
            if run_d >= 6:
                return 'D'
            if rng.random() < 0.15:
                return 'C'
            return 'D'
        else:
            if opp_d >= n - 1 and n >= 5:
                return 'D'
            if rng.random() < 0.1:
                return 'C'
            return 'D'

    if last_me == 'D':
        return 'C'

    run_c = 0
    for a in reversed(opp):
        if a == 'C':
            run_c += 1
        else:
            break
    if run_c >= 4 and n >= 20:
        if opp_d >= 3 and rng.random() < 0.25:
            return 'D'
    return 'C'
